() => {
  const nodes = Array.from(document.querySelectorAll('[data-test*="comment"], [class*="comment"], [id*="comment"]'));
  const snippets = nodes.slice(0, 40).map(n => ({
    tag: n.tagName,
    id: n.id,
    test: n.getAttribute('data-test'),
    cls: (n.className || '').toString().slice(0, 120),
    text: (n.innerText || '').slice(0, 300)
  }));
  const htmlHas = document.documentElement.innerHTML.includes('1100750000304899');
  const gordon = (document.body.innerText || '').includes('Gordon');
  return { htmlHas, gordon, count: nodes.length, snippets };
}

() => {
  const html = document.documentElement.innerHTML;
  const idx = html.indexOf('1100750000304899');
  const around = idx >= 0 ? html.slice(Math.max(0, idx - 500), idx + 1500) : '';
  const authors = Array.from(document.querySelectorAll('[class*="author"], [data-test*="user"], [class*="username"]')).slice(0, 30).map(n => (n.innerText || '').trim().slice(0, 80));
  const replyButtons = Array.from(document.querySelectorAll('button, a, span')).filter(n => /repl|thread|回复|\d+ repl/i.test(n.innerText || '')).map(n => (n.innerText || '').trim().slice(0, 80)).slice(0, 20);
  return { idx, around, authors, replyButtons };
}

async () => {
  const urls = [
    'https://frontdoor-prod-ap-southeast-1-1.clickup.com/comments/v1/comment/1100750000304899',
    'https://frontdoor-prod-ap-southeast-1-1.clickup.com/comments/v2/comment/1100750000304899',
    'https://frontdoor-prod-ap-southeast-1-1.clickup.com/comment-service/v3/workspaces/8553538/comments/1100750000304899',
    'https://frontdoor-prod-ap-southeast-1-1.clickup.com/tasks/v1/task/z941ac1ct6/comment/1100750000304899'
  ];
  const out = [];
  for (const url of urls) {
    try {
      const res = await fetch(url, { credentials: 'include' });
      const text = await res.text();
      out.push({ url, status: res.status, body: text.slice(0, 2000) });
    } catch (e) {
      out.push({ url, error: String(e) });
    }
  }
  return out;
}

async () => {
  const headers = { 'content-type': 'application/json' };
  const attempts = [];
