}

() => {
  const keys = Object.keys(localStorage);
  const interesting = keys.filter(k => /token|auth|session|jwt|cu/i.test(k)).slice(0, 40);
  const samples = interesting.map(k => ({ k, v: String(localStorage.getItem(k)).slice(0, 80) }));
  return { keyCount: keys.length, interesting, samples };
}

