/*
 * Persist the signed-in user's preferred language.
 * POST /user/language is not on the dev gateway; profile update is the supported route.
 */
export function setAppLanguage(params = {}) {
	const memberId = uni.getStorageSync('memberId')
	const preferredLanguage = params.preferredLanguage || params.language
	if (!memberId || !preferredLanguage) {
		return Promise.resolve()
	}
	return httpPut(
		`${hpOrigin}/api/v1/health-passport/user/update/${memberId}`,
		{ preferredLanguage },
		{
			'Content-type': 'application/json;charset=UTF-8'
		}
	)
}
